/* ============================================================
   MR.CLONE.AI — cinematic scroll engine
   ------------------------------------------------------------
   REAL FRAME SEQUENCE UPGRADE (Seedance / Higgsfield hero orbit):
   1) Export frames from your 8s orbit clip:
      ffmpeg -i hero_orbit.mp4 -vf "fps=24,scale=-2:1080" -q:v 3 frames/hero/f_%04d.jpg
   2) Place the `frames` folder next to this HTML file.
   3) Set FRAME_SEQ.enabled = true below. The scrub logic is identical —
      scroll progress maps to frame index instead of the blended turntable.
   ============================================================ */
const FRAME_SEQ = { enabled:false, path:'frames/hero/f_', pad:4, ext:'.jpg', count:192 };

const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const isTouch = window.matchMedia('(pointer:coarse)').matches;
gsap.registerPlugin(ScrollTrigger);
ScrollTrigger.config({ignoreMobileResize:true});

/* ---------- Lenis smooth scroll ---------- */
let lenis = null;
if(!prefersReduced && !isTouch){
  lenis = new Lenis({ lerp:0.09, smoothWheel:true });
  lenis.on('scroll', ScrollTrigger.update);
  gsap.ticker.add((t)=>{ lenis.raf(t*1000); });
  gsap.ticker.lagSmoothing(0);
}

/* ---------- split hero name into letters ---------- */
document.querySelectorAll('.hero-name .lrow').forEach(row=>{
  row.innerHTML = row.dataset.word.split('').map(c=>`<span>${c}</span>`).join('');
});

/* ---------- orbit canvas ---------- */
const IMGS = {
  front:{fig:'data:image/webp;base64,', rim:'data:image/webp;base64,', glow:'data:image/webp;base64,'},
  side2:{fig:'data:image/webp;base64,', rim:'data:image/webp;base64,', glow:'data:image/webp;base64,'},
  back:{fig:'data:image/webp;base64,', rim:'data:image/webp;base64,', glow:'data:image/webp;base64,'},
  side:{fig:'data:image/webp;base64,', rim:'data:image/webp;base64,', glow:'data:image/webp;base64,'}
};
const ORDER = ['front','side2','back','side']; // 0° / 90° / 180° / 270°
const canvas = document.getElementById('orbit');
const ctx = canvas.getContext('2d');
let views = {}, loaded = 0, TOTAL = 12;
let targetAngle = 0, angle = 0, mx = 0, my = 0, tmx = 0, tmy = 0;
let frames = [], framesReady = false;

function loadImg(src){ const i = new Image(); i.src = src; i.onload = ()=>loaded++; return i; }
ORDER.forEach(k=>{ views[k] = { fig:loadImg(IMGS[k].fig), rim:loadImg(IMGS[k].rim), glow:loadImg(IMGS[k].glow) }; });
if(FRAME_SEQ.enabled){
  for(let i=1;i<=FRAME_SEQ.count;i++){
    const n = String(i).padStart(FRAME_SEQ.pad,'0');
    frames.push(loadImg(FRAME_SEQ.path+n+FRAME_SEQ.ext));
  }
  framesReady = true;
}

/* dust particles */
const dust = Array.from({length:44},(_,i)=>({
  x:Math.random(), y:Math.random(), s:Math.random()*1.6+0.4,
  v:Math.random()*0.00028+0.00006, a:Math.random()*0.16+0.03, p:Math.random()*Math.PI*2,
  c:i%2? 'rgba(62,242,155,1)':'rgba(242,235,220,1)'
}));
let heroVisible = true, floorGrad = null, vigGrad = null, gradKey = '';

function sizeCanvas(){
  const dpr = Math.min(window.devicePixelRatio||1, 2);
  canvas.width = canvas.clientWidth*dpr; canvas.height = canvas.clientHeight*dpr;
  ctx.setTransform(dpr,0,0,dpr,0,0);
  gradKey = '';
}
window.addEventListener('resize', sizeCanvas); sizeCanvas();
window.addEventListener('pointermove', e=>{
  tmx = (e.clientX/window.innerWidth - .5); tmy = (e.clientY/window.innerHeight - .5);
});

const smooth = t=>t*t*(3-2*t);

function drawView(v, w, cx, baseY, figH, slide){
  if(w<=0.004) return;
  const ar = v.fig.naturalWidth/v.fig.naturalHeight || 0.32;
  const fw = figH*ar;
  const x = cx - fw/2 + slide;
  /* aura */
  ctx.globalCompositeOperation='lighter';
  ctx.globalAlpha = w*0.55;
  ctx.drawImage(v.glow, x-fw*0.16, baseY-figH*1.06, fw*1.32, figH*1.12);
  /* figure */
  ctx.globalCompositeOperation='source-over';
  ctx.globalAlpha = w;
  ctx.drawImage(v.fig, x, baseY-figH, fw, figH);
  /* emerald rim */
  ctx.globalCompositeOperation='lighter';
  ctx.globalAlpha = w*0.9;
  ctx.drawImage(v.rim, x, baseY-figH, fw, figH);
  /* reflection */
  ctx.globalCompositeOperation='source-over';
  ctx.save();
  ctx.globalAlpha = w*0.14;
  ctx.translate(x+fw/2, baseY*2 + 2);
  ctx.scale(1,-1);
  ctx.drawImage(v.fig, -fw/2, baseY-figH, fw, figH);
  ctx.restore();
}

function render(){
  if(!heroVisible){ requestAnimationFrame(render); return; }
  const W = canvas.clientWidth, H = canvas.clientHeight;
  ctx.clearRect(0,0,W,H);
  angle += (targetAngle-angle)*0.11;
  mx += (tmx-mx)*0.05; my += (tmy-my)*0.05;

  const cx = W/2 + mx*-16;
  const figH = Math.min(H*0.74, 900);
  const baseY = H*0.90 + my*-8;

  /* cached gradients */
  if(gradKey !== W+'x'+H){
    gradKey = W+'x'+H;
    floorGrad = ctx.createRadialGradient(W/2, H*0.90, 10, W/2, H*0.90, figH*0.55);
    floorGrad.addColorStop(0,'rgba(62,242,155,0.10)'); floorGrad.addColorStop(1,'rgba(62,242,155,0)');
    vigGrad = ctx.createRadialGradient(W/2,H/2,H*0.32,W/2,H/2,H*0.85);
    vigGrad.addColorStop(0,'rgba(5,5,6,0)'); vigGrad.addColorStop(1,'rgba(5,5,6,0.66)');
  }
  ctx.globalAlpha=1; ctx.fillStyle=floorGrad;
  ctx.fillRect(W/2-figH, H*0.90-figH*0.3, figH*2, figH*0.6);

  /* dust */
  const now = performance.now()*0.001;
  for(const d of dust){
    d.y -= d.v; if(d.y<0) d.y=1;
    ctx.globalAlpha = d.a*(0.6+0.4*Math.sin(now + d.p));
    ctx.fillStyle = d.c;
    ctx.fillRect(d.x*W + Math.sin(d.y*9+d.p)*10 + mx*-30*d.s, d.y*H, d.s, d.s);
  }

  if(FRAME_SEQ.enabled && framesReady && frames.length){
    const idx = Math.min(frames.length-1, Math.floor((angle%360)/360*frames.length));
    const f = frames[idx];
    if(f && f.complete && f.naturalWidth){
      const fr = f.naturalWidth/f.naturalHeight;
      let dw = W, dh = W/fr; if(dh<H){ dh=H; dw=H*fr; }
      ctx.globalAlpha=1; ctx.drawImage(f,(W-dw)/2,(H-dh)/2,dw,dh);
    }
  } else {
    const a = ((angle%360)+360)%360;
    const sector = a/90;
    const i = Math.floor(sector)%4, j = (i+1)%4;
    const t = smooth(sector - Math.floor(sector));
    const dir = 26; /* px sweep during transition */
    drawView(views[ORDER[i]], 1-t, cx, baseY, figH, -t*dir);
    drawView(views[ORDER[j]], t,   cx, baseY, figH, (1-t)*dir);
  }

  /* vignette */
  ctx.globalCompositeOperation='source-over'; ctx.globalAlpha=1;
  ctx.fillStyle=vigGrad; ctx.fillRect(0,0,W,H);

  requestAnimationFrame(render);
}
requestAnimationFrame(render);

