/* ---------- custom cursor + magnetic CTAs (desktop only) ---------- */
if (window.matchMedia('(pointer:fine)').matches && !prefersReduced){
  document.body.classList.add('cursor-on');
  const dot = document.getElementById('curDot'), ring = document.getElementById('curRing');
  let mx=-100, my=-100, rx=-100, ry=-100, seen=false;
  window.addEventListener('mousemove', e=>{
    mx=e.clientX; my=e.clientY;
    if(!seen){ rx=mx; ry=my; dot.style.opacity=1; ring.style.opacity=1; seen=true; }
  }, {passive:true});
  gsap.ticker.add(()=>{
    if(!seen) return;
    rx += (mx-rx)*0.16; ry += (my-ry)*0.16;
    dot.style.transform = `translate(${mx}px,${my}px) translate(-50%,-50%)`;
    ring.style.transform = `translate(${rx}px,${ry}px) translate(-50%,-50%)`;
  });
  document.querySelectorAll('a, button, .work-card, .faq-q').forEach(el=>{
    el.addEventListener('mouseenter', ()=>ring.classList.add('hot'));
    el.addEventListener('mouseleave', ()=>ring.classList.remove('hot'));
  });
  document.querySelectorAll('.btn-solid, .btn-ghost, .header-cta').forEach(el=>{
    el.addEventListener('mousemove', e=>{
      const r = el.getBoundingClientRect();
      gsap.to(el, {x:(e.clientX-r.left-r.width/2)*0.22, y:(e.clientY-r.top-r.height/2)*0.3,
                   duration:0.4, ease:'power2.out'});
    });
    el.addEventListener('mouseleave', ()=>gsap.to(el, {x:0, y:0, duration:0.7, ease:'elastic.out(1,0.45)'}));
  });
}


/* ---------- showreel (self-hosted mp4) ---------- */
(function(){
  const reel = document.getElementById('reelVideo');
  if(!reel) return;

  const play = ()=>{ const p = reel.play(); if(p && p.catch) p.catch(()=>{}); };
  reel.muted = true;
  play();

  /* the reel plays only while it is on screen */
  if('IntersectionObserver' in window){
    new IntersectionObserver(en=>{
      en.forEach(x=>{ x.isIntersecting ? play() : reel.pause(); });
    },{threshold:.25}).observe(reel);
  }

  /* sound toggle on the reel */
  const sb = document.getElementById('reelSound');
  if(sb){
    sb.addEventListener('click', ()=>{
      reel.muted = !reel.muted;
      if(!reel.muted) play();
      sb.textContent = reel.muted ? '🔇 Sound on' : '🔊 Sound off';
    });
  }

  /* a sample taking over kills the reel's sound */
  document.addEventListener('mrclone:sample-play', ()=>{
    reel.pause();
    reel.muted = true;
    if(sb) sb.textContent = '🔇 Sound on';
  });
})();

/* ---------- work samples (YouTube IFrame API) ---------- */
(function(){
  const wraps = [...document.querySelectorAll('.sample')].filter(w=>w.querySelector('[data-yt]'));
  if(!wraps.length) return;

  const players = new Map();   /* wrapper -> YT.Player */

  window.onYouTubeIframeAPIReady = function(){
    wraps.forEach(wrap=>{
      const mount = wrap.querySelector('[data-yt]');
      const player = new YT.Player(mount, {
        videoId: mount.dataset.yt,
        playerVars:{controls:1, modestbranding:1, rel:0, playsinline:1, iv_load_policy:3},
        events:{ onReady: e => { players.set(wrap, e.target); watch(wrap, e.target); } }
      });
    });
  };

  /* a sample pauses once it leaves the viewport */
  function watch(wrap, player){
    if(!('IntersectionObserver' in window)) return;
    new IntersectionObserver(en=>{
      en.forEach(x=>{ if(!x.isIntersecting) player.pauseVideo(); });
    },{threshold:.1}).observe(wrap);
  }

  /* first click starts the sample with sound and hands over to YouTube's controls */
  wraps.forEach(wrap=>{
    wrap.addEventListener('click', ()=>{
      const player = players.get(wrap);
      if(!player || wrap.classList.contains('playing')) return;
      document.dispatchEvent(new CustomEvent('mrclone:sample-play'));
      players.forEach((other, w)=>{ if(w !== wrap) other.pauseVideo(); });
      player.unMute();
      player.playVideo();
      wrap.classList.add('playing');
    });
  });

  /* load the API */
  const tag = document.createElement('script');
  tag.src = 'https://www.youtube.com/iframe_api';
  document.head.appendChild(tag);
})();

